/* Approved staging-only pilot CLI. No deploy or Cloudflare mutations. */
import fs from 'node:fs';import crypto from 'node:crypto';
import {createNodeHttpD1BridgeA3} from './batch05a3-http-d1-bridge.js';
import {runBatch05aSmoke} from './batch05a-smoke-orchestrator.mjs';
const [,,cmd,config]=process.argv;
if(!['preflight','run','stop','export'].includes(cmd)||!config)throw Error('USAGE: eligible-cli <preflight|run|stop|export> <config.json>');
const c=JSON.parse(fs.readFileSync(config,'utf8'));
const pinned='FE-B05A-ELIGIBLE-PILOT-01';
if(c.pilot_id!==pinned)throw Error('FIXED_PILOT_ID_REQUIRED');
if(c.staging_target_confirmed!==true||c.production_target_forbidden!==true||!/football-edge-b05a-staging-bridge\./.test(c.bridge_base_url)||!c.bridge_base_url.startsWith('https://'))throw Error('STAGING_TARGET_GUARD');
if(c.hard_limits?.fixtures!==1||c.hard_limits?.provider_attempts!==40||c.hard_limits?.duration_ms!==600000||c.max_ticks!==4)throw Error('PILOT_SCOPE_GUARD');
const model=crypto.createHash('sha256').update(fs.readFileSync(new URL('../prediction_v2/probability-engine.js',import.meta.url))).digest('hex');if(model!=='194b0c5b9870dbdcb4e06b2a823e1b0afd81f6626fb98c44917172de87257b16')throw Error('MODEL_SHA_MISMATCH');
if(cmd==='preflight'){console.log(JSON.stringify({ok:true,pilot_id:pinned,model_sha:model,provider_attempt_cap:40,selection_cap:20,reserved_postpin:20,max_ticks:4,network_calls:0,remote_mutations:0},null,2));process.exit(0)}
const token=process.env[c.bridge_token_env||'BATCH05A3_BRIDGE_TOKEN'];if(!token)throw Error('BRIDGE_TOKEN_REQUIRED');const client=createNodeHttpD1BridgeA3({baseUrl:c.bridge_base_url,token,pilotId:c.pilot_id,ownerId:c.owner_id});
if(cmd==='export'){console.log(JSON.stringify(await client.exportEvidence(),null,2));process.exit(0)}
if(cmd==='stop'){console.log(JSON.stringify(await client.requestStop(),null,2));process.exit(0)}
if(process.env.FE_APPROVE_ELIGIBLE_PILOT!=='YES')throw Error('EXPLICIT_ELIGIBLE_PILOT_APPROVAL_REQUIRED');
// Read-only gate BEFORE acquiring lease or calling the provider.
const prior=await client.budgetStore.load(),session=await client.sessionStore.load();if(prior?.stop_reason||session?.stop_reason)throw Error('DURABLE_STOP_ACTIVE');if(Number(prior?.total_requests||0)>=40)throw Error('DURABLE_BUDGET_EXHAUSTED');if(Boolean(prior)!==Boolean(session))throw Error('DURABLE_RESTART_STATE_MISMATCH');
const apiKey=process.env[c.api_key_env||'APISPORTS_KEY'];if(!apiKey)throw Error('API_KEY_MISSING');
const clock={now:()=>Date.now(),sleep:ms=>new Promise(r=>setTimeout(r,ms))};const result=await runBatch05aSmoke({env:{APISPORTS_KEY:apiKey},fetchImpl:fetch,captureSink:client.captureSink,persistLockedBundle:client.persistLockedBundle,clock,store:client.budgetStore,sessionStore:client.sessionStore,loadPersistedCaptures:client.loadPersistedCaptures,loadObservation:client.loadObservation,owner:client.owner,pilotId:c.pilot_id,maxTicks:4,eligiblePilot:true,ackMode:'REMOTE',networkReal:true,transportLabel:'STAGING_B05A_ELIGIBLE_V2'});
console.log(JSON.stringify(result,null,2));if(result.failure||result.observation_ids.length<4||result.invocation_provider_attempts>40)process.exitCode=2;

/* Batch04.1 — executable pilot budget/pacing controller.
 * Every HTTP attempt, including /status, discovery, live/context endpoints and retries,
 * must acquire a token here. State is persisted BEFORE request start.
 * Restart without state fails closed; restart with unresolved in-flight requests also fails closed.
 */
const num=v=>v===null||v===undefined||v===''?null:(Number.isFinite(Number(v))?Number(v):null);
const clone=v=>JSON.parse(JSON.stringify(v));
const sysClock={now:()=>Date.now(),sleep:ms=>new Promise(r=>setTimeout(r,ms))};
export const DEFAULT_PILOT_LIMITS=Object.freeze({
  max_requests_total:3000,
  max_requests_per_minute:30,
  provider_minute_fraction:.50,
  max_concurrency:4,
  request_start_gap_ms:250,
  duration_ms:90*60*1000,
  daily_reserve_min:10000,
  daily_reserve_fraction:.20,
  minute_safety_remaining:2,
  repeated_429_stop:2
});

export class MemoryBudgetStateStore{
  constructor(seed=null){this.value=seed?clone(seed):null}
  async load(){return this.value?clone(this.value):null}
  async save(v){this.value=clone(v)}
}
export function createD1BudgetStateStore(db,pilotId){
  if(!db)throw new Error('B4_BUDGET_DB_REQUIRED');
  return {
    async load(){const r=await db.prepare('SELECT state_json FROM b4_pilot_budget_state WHERE pilot_id=?').bind(pilotId).first();return r?.state_json?JSON.parse(r.state_json):null},
    async save(v){await db.prepare(`INSERT INTO b4_pilot_budget_state(pilot_id,state_json,updated_at) VALUES(?,?,CURRENT_TIMESTAMP)
      ON CONFLICT(pilot_id) DO UPDATE SET state_json=excluded.state_json,updated_at=CURRENT_TIMESTAMP`).bind(pilotId,JSON.stringify(v)).run()}
  };
}
function initialState(pilotId,now,limits){return {
  schema:'FE_PV2_PILOT_BUDGET_STATE_V2',pilot_id:pilotId,started_at_ms:now,last_request_start_ms:null,request_starts_ms:[],total_requests:0,in_flight:0,stop_reason:null,
  daily_verified:false,daily_limit:null,daily_remaining:null,minute_verified:false,minute_limit:null,minute_remaining:null,consecutive_429:0,limits:{...limits}
}}
export class PilotBudgetController{
  constructor({pilotId,store,clock=sysClock,limits={},allowNewPilot=false}={}){
    if(!pilotId)throw new Error('B4_PILOT_ID_REQUIRED');
    if(!store)throw new Error('B4_BUDGET_STATE_STORE_REQUIRED');
    this.pilotId=pilotId;this.store=store;this.clock=clock;this.limits={...DEFAULT_PILOT_LIMITS,...limits};this.allowNewPilot=allowNewPilot;
    this.selectionMode=false;this.state=null;this.initialized=false;this._initPromise=null;this._mutex=Promise.resolve();
  }
  async _withLock(fn){const run=this._mutex.then(fn,fn);this._mutex=run.then(()=>undefined,()=>undefined);return run}
  async init(){
    if(this.initialized)return this;
    if(this._initPromise){await this._initPromise;return this}
    this._initPromise=(async()=>{
      const loaded=await this.store.load();
      if(loaded){
        if(String(loaded.pilot_id)!==String(this.pilotId))throw new Error('B4_BUDGET_PILOT_ID_MISMATCH');
        this.state=loaded;this.state.limits={...this.limits,...(loaded.limits||{})};this.limits={...this.state.limits};
        // A process restart cannot know whether previously in-flight HTTP attempts completed.
        // Fail closed rather than silently freeing those slots and double-spending budget.
        if(Number(this.state.in_flight||0)>0&&!this.state.stop_reason){this.state.stop_reason='RESTART_WITH_INFLIGHT_REQUESTS';await this.store.save(this.state)}
      }else{
        if(!this.allowNewPilot)throw new Error('B4_BUDGET_STATE_MISSING_FAIL_CLOSED');
        this.state=initialState(this.pilotId,this.clock.now(),this.limits);await this.store.save(this.state);
      }
      this.initialized=true;
    })();
    try{await this._initPromise}finally{this._initPromise=null}
    return this;
  }
  snapshot(){if(!this.state)throw new Error('B4_BUDGET_NOT_INITIALIZED');return clone(this.state)}
  async persist(){await this.store.save(this.state)}
  _dailyReserve(){const l=num(this.state.daily_limit),min=Number(this.limits.daily_reserve_min)||0,frac=Number(this.limits.daily_reserve_fraction)||0;return l==null?min:Math.max(min,Math.ceil(l*frac))}
  _rollingCap(){
    const configured=Math.max(1,Number(this.limits.max_requests_per_minute)||1),provider=num(this.state.minute_limit);
    if(provider==null)return configured;
    const frac=Math.max(0.01,Math.min(1,Number(this.limits.provider_minute_fraction)||.5));
    return Math.max(1,Math.min(configured,Math.floor(provider*frac)));
  }
  async _haltLocked(reason){if(!this.state.stop_reason)this.state.stop_reason=String(reason||'STOPPED');await this.persist();return clone(this.state)}
  async halt(reason){await this.init();return this._withLock(()=>this._haltLocked(reason))}
  async updateProviderQuota({dailyLimit=null,dailyRemaining=null,minuteLimit=null,minuteRemaining=null}={}){
    await this.init();return this._withLock(async()=>{
      if(num(dailyLimit)!=null&&num(dailyRemaining)!=null){this.state.daily_verified=true;this.state.daily_limit=num(dailyLimit);this.state.daily_remaining=num(dailyRemaining)}
      if(num(minuteLimit)!=null&&num(minuteRemaining)!=null){this.state.minute_verified=true;this.state.minute_limit=num(minuteLimit);this.state.minute_remaining=num(minuteRemaining)}
      await this.persist();return clone(this.state);
    });
  }
  setSelectionMode(v){this.selectionMode=Boolean(v)}
  async acquire({kind='DATA'}={}){
    await this.init();
    for(;;){
      const decision=await this._withLock(async()=>{
        const now=this.clock.now();
        const stop=async reason=>{await this._haltLocked(reason);return {error:`B4_PILOT_STOPPED:${reason}`}};
        if(this.state.stop_reason)return {error:`B4_PILOT_STOPPED:${this.state.stop_reason}`};
        if(now-this.state.started_at_ms>=Number(this.limits.duration_ms))return stop('DURATION_CAP');
        if(this.state.total_requests>=Number(this.limits.max_requests_total))return stop('TOTAL_REQUEST_CAP');
        // Reserve 20 post-pin attempts. This gate is evaluated before any provider call.
        if(this.selectionMode&&(Number(this.state.selection_attempts||0)>=20||this.state.total_requests>=Number(this.limits.max_requests_total)-20))return {error:'SELECTION_RESERVE_GUARD'};
        if(String(kind)!=='STATUS'&&!this.state.minute_verified)return stop('MINUTE_QUOTA_UNVERIFIED');
        if(String(kind)!=='STATUS'&&!this.state.daily_verified)return stop('DAILY_QUOTA_UNVERIFIED');
        if(this.state.daily_verified&&num(this.state.daily_remaining)!=null&&this.state.daily_remaining<=this._dailyReserve())return stop('DAILY_RESERVE_GUARD');
        if(this.state.minute_verified&&num(this.state.minute_remaining)!=null&&this.state.minute_remaining<=Number(this.limits.minute_safety_remaining))return stop('MINUTE_REMAINING_GUARD');
        this.state.request_starts_ms=(this.state.request_starts_ms||[]).filter(t=>now-Number(t)<60000);
        const cap=this._rollingCap();
        if(this.state.request_starts_ms.length>=cap){const wait=Math.max(1,60000-(now-Number(this.state.request_starts_ms[0])));return {wait}}
        if(Number(this.state.in_flight||0)>=Number(this.limits.max_concurrency))return {wait:Math.max(1,Number(this.limits.request_start_gap_ms)||1)};
        const last=num(this.state.last_request_start_ms),gap=Math.max(0,Number(this.limits.request_start_gap_ms)||0);
        if(last!=null&&now-last<gap)return {wait:gap-(now-last)};
        const start=this.clock.now();
        this.state.total_requests+=1;if(this.selectionMode)this.state.selection_attempts=Number(this.state.selection_attempts||0)+1;this.state.in_flight=Number(this.state.in_flight||0)+1;this.state.last_request_start_ms=start;this.state.request_starts_ms.push(start);
        if(this.state.minute_remaining!=null)this.state.minute_remaining=Math.max(0,this.state.minute_remaining-1);
        if(this.state.daily_remaining!=null)this.state.daily_remaining=Math.max(0,this.state.daily_remaining-1);
        await this.persist();
        return {token:{pilot_id:this.pilotId,request_number:this.state.total_requests,started_at_ms:start,kind}};
      });
      if(decision.token)return decision.token;
      if(decision.error)throw new Error(decision.error);
      await this.clock.sleep(Math.max(1,Number(decision.wait)||1));
    }
  }
  async release(token,{status=null,headers=null,persistenceOk=true}={}){
    await this.init();return this._withLock(async()=>{
      this.state.in_flight=Math.max(0,Number(this.state.in_flight||0)-1);
      const get=k=>headers?.get?.(k)??headers?.[k]??headers?.[String(k).toLowerCase()]??null,
        dl=num(get('x-ratelimit-requests-limit')),dr=num(get('x-ratelimit-requests-remaining')),ml=num(get('x-ratelimit-limit')),mr=num(get('x-ratelimit-remaining'));
      if(dl!=null&&dr!=null){this.state.daily_verified=true;this.state.daily_limit=dl;this.state.daily_remaining=dr}
      if(ml!=null&&mr!=null){this.state.minute_verified=true;this.state.minute_limit=ml;this.state.minute_remaining=mr}
      if(Number(status)===429)this.state.consecutive_429=Number(this.state.consecutive_429||0)+1;else if(status!=null)this.state.consecutive_429=0;
      if(!persistenceOk&&!this.state.stop_reason)this.state.stop_reason='PERSISTENCE_FAILURE';
      if(this.state.consecutive_429>=Number(this.limits.repeated_429_stop)&&!this.state.stop_reason)this.state.stop_reason='REPEATED_HTTP_429';
      if(this.state.daily_verified&&num(this.state.daily_remaining)!=null&&this.state.daily_remaining<=this._dailyReserve()&&!this.state.stop_reason)this.state.stop_reason='DAILY_RESERVE_GUARD';
      if(this.state.minute_verified&&num(this.state.minute_remaining)!=null&&this.state.minute_remaining<=Number(this.limits.minute_safety_remaining)&&!this.state.stop_reason)this.state.stop_reason='MINUTE_REMAINING_GUARD';
      await this.persist();return clone(this.state);
    });
  }
}

/* Batch04.1 staging-only collector core. No automatic schedule/deploy.
 * All HTTP attempts — /status, discovery, live, context and retries — MUST pass
 * through PilotBudgetController. No approved pilot => no network calls.
 */
import {buildCapturedPayload} from '../prediction_v2/capture-contract.js';
import {evaluateFixture,deriveMatchPhase} from './fixture-eligibility-selector.js';
const BASE='https://v3.football.api-sports.io';
const LIVE=new Set(['1H','HT','2H','ET','BT','INT','LIVE','P']);
const num=v=>v===null||v===undefined||v===''?null:(Number.isFinite(Number(v))?Number(v):null);
const isoAt=ms=>new Date(ms).toISOString();
function quotaHeaders(h){return {daily_limit:num(h?.get?.('x-ratelimit-requests-limit')),daily_remaining:num(h?.get?.('x-ratelimit-requests-remaining')),minute_limit:num(h?.get?.('x-ratelimit-limit')),minute_remaining:num(h?.get?.('x-ratelimit-remaining'))}}
export async function persistCaptureD1(db,r){if(!db)throw new Error('STAGING_DB_REQUIRED');await db.prepare(`INSERT INTO b4_capture_payloads(record_id,request_id,source_id,provider,endpoint,fixture_id,market_period,received_at,provider_updated_at,payload_hash,capture_status,payload_json,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(record_id) DO NOTHING`).bind(r.record_id,r.request_id,r.source_id,r.provider,r.endpoint,r.fixture_id,r.market_period,r.received_at,r.provider_updated_at,r.payload_hash,r.capture_status,JSON.stringify(r.payload??null),JSON.stringify(r.metadata??null)).run();const row=await db.prepare('SELECT record_id,payload_hash FROM b4_capture_payloads WHERE record_id=?').bind(r.record_id).first();if(!row||row.payload_hash!==r.payload_hash)throw new Error('B4_CAPTURE_DURABLE_READBACK_MISMATCH');return r}
function headersOf(res){return res?.headers??null}
function responseOk(status){return Number(status)>=200&&Number(status)<300}
export async function providerGet({env,db,captureSink=null,budget,endpoint,params={},fixtureId=null,period=null,metadata=null,fetchImpl=fetch,retries=0}={}){
  if(!env?.APISPORTS_KEY)throw new Error('APISPORTS_KEY_MISSING');if(!budget)throw new Error('B4_BUDGET_CONTROLLER_REQUIRED');await budget.init();let lastRecord=null,lastError=null;
  for(let attempt=0;attempt<=Math.max(0,Number(retries)||0);attempt++){
    const token=await budget.acquire({kind:endpoint==='/status'?'STATUS':'DATA'}),started=isoAt(token.started_at_ms),url=`${BASE}${endpoint}?${new URLSearchParams(params)}`;let res,text,payload,error=null,status=null,headers=null,persisted=true;
    try{res=await fetchImpl(url,{headers:{'x-apisports-key':env.APISPORTS_KEY,accept:'application/json'}});status=res.status;headers=headersOf(res);text=await res.text();try{payload=JSON.parse(text)}catch{payload=null;error=new Error('INVALID_JSON')}}catch(e){error=e}
    const received=isoAt(budget.clock?.now?.()??Date.now()),qh=quotaHeaders(headers),record=await buildCapturedPayload({provider:'API_FOOTBALL',source:'BATCH041_STAGING_COLLECTOR',endpoint,params,fixtureId,period,requestStartedAt:started,receivedAt:received,httpStatus:status,fetchError:error,payload,rawText:text,
      metadata:{...(metadata||{}),attempt,quota:qh}});lastRecord=record;
    try{if(db)await persistCaptureD1(db,record);else if(typeof captureSink==='function')await captureSink(record)}catch(e){persisted=false;lastError=e}
    await budget.release(token,{status,headers,persistenceOk:persisted});
    if(!persisted)throw lastError;
    if(!error&&responseOk(status))return record;
    lastError=error||new Error(`API_HTTP_${status}`);
    if(attempt>=Math.max(0,Number(retries)||0))break;
    const snap=budget.snapshot();if(snap.stop_reason)break;await budget.clock.sleep(Math.max(1000,Number(budget.limits?.request_start_gap_ms)||250));
  }
  if(lastRecord)return lastRecord;throw lastError||new Error('B4_PROVIDER_REQUEST_FAILED');
}
export async function fetchProviderQuota({env,db=null,captureSink=null,budget,fetchImpl=fetch}={}){
  const r=await providerGet({env,db,captureSink,budget,endpoint:'/status',params:{},metadata:{role:'PROVIDER_STATUS'},fetchImpl,retries:0}),body=Array.isArray(r?.payload?.response)?r.payload.response[0]:r?.payload?.response,
    current=num(body?.requests?.current),limit_day=num(body?.requests?.limit_day),remaining=current!=null&&limit_day!=null?Math.max(0,limit_day-current):null,plan=body?.subscription?.plan??null,q=r?.metadata?.quota||{};
  if(current!=null&&limit_day!=null)await budget.updateProviderQuota({dailyLimit:limit_day,dailyRemaining:remaining,minuteLimit:q.minute_limit,minuteRemaining:q.minute_remaining});
  const snap=budget.snapshot();
  if(snap.stop_reason)return {verified:false,record:r,reason:snap.stop_reason,budget:snap};
  if(r.capture_status!=='OK'||current==null||limit_day==null)return {verified:false,record:r,reason:'PROVIDER_DAILY_QUOTA_UNVERIFIED',budget:snap};
  if(!snap.minute_verified)return {verified:false,record:r,reason:'PROVIDER_MINUTE_QUOTA_UNVERIFIED',budget:snap};
  return {verified:true,current,limit_day,remaining,plan,minute_limit:snap.minute_limit,minute_remaining:snap.minute_remaining,record:r,budget:snap};
}
function liveFixtures(record){return (record?.payload?.response||[]).filter(f=>LIVE.has(String(f?.fixture?.status?.short||'').toUpperCase())&&Number.isFinite(Number(f?.fixture?.id))).sort((a,b)=>Number(a.fixture.id)-Number(b.fixture.id))}
export async function capturePilotTick({env,db,captureSink=null,budget,fetchImpl=fetch,maxFixtures=8}={}){
  if(!budget)throw new Error('B4_BUDGET_CONTROLLER_REQUIRED');const quota=await fetchProviderQuota({env,db,captureSink,budget,fetchImpl});if(!quota.verified){await budget.halt(quota.reason);return {status:'STOP',reason:quota.reason,records:[quota.record],budget:budget.snapshot()}}
  const records=[quota.record],discovery=await providerGet({env,db,captureSink,budget,endpoint:'/fixtures',params:{live:'all'},metadata:{role:'LIVE_UNIVERSE_DISCOVERY'},fetchImpl,retries:1});records.push(discovery);const fixtures=liveFixtures(discovery).slice(0,Math.max(0,Number(maxFixtures)||0));
  try{for(const f of fixtures){const fid=Number(f.fixture.id);for(const spec of [['/fixtures/statistics',{fixture:fid},'LIVE_STATS'],['/fixtures/events',{fixture:fid},'EVENTS'],['/odds/live',{fixture:fid},'LIVE_MARKET']])records.push(await providerGet({env,db,captureSink,budget,endpoint:spec[0],params:spec[1],fixtureId:fid,metadata:{role:spec[2],identity:{fixture_id:fid}},fetchImpl,retries:1}))}}
  catch(e){return {status:'STOP',reason:budget.snapshot().stop_reason||String(e?.message||e),quota,fixtures:fixtures.map(x=>x.fixture.id),records,budget:budget.snapshot()}}
  return {status:'OK',quota,fixtures:fixtures.map(x=>x.fixture.id),records,selection_policy:'FIXTURE_ID_ASC_NOT_OLD_RANK',budget:budget.snapshot()};
}
export async function captureSlowContext({env,db,captureSink=null,budget,fixture,fetchImpl=fetch,maxRequests=20}={}){
  if(!budget)throw new Error('B4_BUDGET_CONTROLLER_REQUIRED');await budget.init();const snap=budget.snapshot();if(!snap.minute_verified||!snap.daily_verified)return {status:'STOP',reason:!snap.minute_verified?'MINUTE_QUOTA_UNVERIFIED':'DAILY_QUOTA_UNVERIFIED',records:[]};
  const f=fixture,league=f?.league?.id,season=f?.league?.season,home=f?.teams?.home?.id,away=f?.teams?.away?.id,fid=f?.fixture?.id;if(![league,season,home,away,fid].every(x=>x!=null))return {status:'SKIP',reason:'CONTEXT_KEYS_MISSING',records:[]};
  const specs=[['/fixtures/lineups',{fixture:fid},'LINEUPS',null],['/fixtures/players',{fixture:fid},'FIXTURE_PLAYERS',null],['/injuries',{fixture:fid},'INJURIES',null],['/predictions',{fixture:fid},'PREDICTIONS',null],['/standings',{league,season},'STANDINGS',null],
    ['/teams/statistics',{league,season,team:home},'HOME_TEAM_STATS',home],['/teams/statistics',{league,season,team:away},'AWAY_TEAM_STATS',away],['/fixtures',{team:home,last:8},'HOME_RECENT',home],['/fixtures',{team:away,last:8},'AWAY_RECENT',away],
    ['/players',{team:home,season,page:1},'HOME_SEASON_PLAYERS',home],['/players',{team:away,season,page:1},'AWAY_SEASON_PLAYERS',away]];
  const records=[];try{for(const [endpoint,params,role,teamId] of specs.slice(0,maxRequests))records.push(await providerGet({env,db,captureSink,budget,endpoint,params,fixtureId:fid,metadata:{role,identity:{fixture_id:fid,league_id:league,season,team_id:teamId}},fetchImpl,retries:1}))}catch(e){return {status:'STOP',reason:budget.snapshot().stop_reason||String(e?.message||e),records,budget:budget.snapshot()}}
  return {status:'OK',records,budget:budget.snapshot()};
}

// Batch05A.1 pinned-scope tick. Discovery remains a provider-universe observation;
// detailed enrichment is restricted to the immutable selected fixture.
export async function capturePinnedSmokeTick({env,db,captureSink=null,budget,fetchImpl=fetch,pinnedFixtureId=null,eligibleMode=false}={}){
  if(!budget)throw new Error('B4_BUDGET_CONTROLLER_REQUIRED');
  if(eligibleMode&&pinnedFixtureId==null)budget.setSelectionMode(true);
  const quota=await fetchProviderQuota({env,db,captureSink,budget,fetchImpl});
  if(!quota.verified){await budget.halt(quota.reason);return {status:'STOP',reason:quota.reason,records:[quota.record],pinned_fixture_id:pinnedFixtureId,budget:budget.snapshot()}}
  const records=[quota.record];
  let discovery;
  try{discovery=await providerGet({env,db,captureSink,budget,endpoint:'/fixtures',params:{live:'all'},metadata:{role:'LIVE_UNIVERSE_DISCOVERY'},fetchImpl,retries:0});records.push(discovery)}
  catch(e){return {status:'STOP',reason:budget.snapshot().stop_reason||String(e?.message||e),records,pinned_fixture_id:pinnedFixtureId,budget:budget.snapshot()}}
